package com.openlap.plugins.storage;

import com.mongodb.DBRef;
import com.mongodb.MongoClient;
import com.mongodb.MongoClientURI;
import com.openlap.plugins.artifacts.ArtifactIntegrity;
import com.openlap.plugins.artifacts.PluginArtifact;
import com.openlap.plugins.artifacts.PluginKind;
import com.openlap.plugins.artifacts.S3ArtifactObjectStore;
import java.io.InputStream;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.bson.Document;
import static com.mongodb.client.model.Filters.eq;

/** Generated bytes and cold native clients only; never executes a plugin. */
public final class CombinedPluginRecoveryFixture {
  static final String DATABASE = "plugin_recovery_fixture";
  static final Object[][] VERSIONS = {
      {"current", PluginKind.ANALYTICS, "READY", true},
      {"older", PluginKind.ANALYTICS, "READY", true},
      {"removed", PluginKind.VISUALIZATION, "READY", true},
      {"discarded", PluginKind.ANALYTICS, "READY", true},
      {"staged-present", PluginKind.ANALYTICS, "STAGED", true},
      {"staged-absent", PluginKind.VISUALIZATION, "STAGED", false},
      {"purged", PluginKind.ANALYTICS, "PURGED", false},
      {"orphan", PluginKind.VISUALIZATION, "ORPHAN", true}};
  static void require(boolean okay) { if (!okay) throw new IllegalStateException("Combined recovery fixture mismatch."); }
  static PluginArtifact artifact(Object[] row) throws Exception { return PluginObjectSnapshotQualification.artifact((String) row[0], (PluginKind) row[1]); }
  static Map<String, Object> description(Object[] row) throws Exception {
    PluginArtifact artifact = artifact(row); Map<String, Object> value = new LinkedHashMap<>();
    value.put("label", row[0]); value.put("_id", artifact.getId()); value.put("kind", row[1].toString()); value.put("state", row[2]);
    value.put("sha256", artifact.getSha256()); value.put("sizeBytes", artifact.getSizeBytes()); value.put("objectKey", artifact.getObjectKey()); return value;
  }
  static void prepare(boolean empty) throws Exception {
    List<Object> descriptions = new ArrayList<>();
    VersityStorageApplication.Settings settings = new VersityStorageApplication.Settings(false);
    URI endpoint = URI.create(System.getenv("PLUGIN_STORAGE_S3_ENDPOINT"));
    try (S3ArtifactObjectStore store = S3ArtifactObjectStore.connect(PluginObjectSnapshotApplication.properties(settings, endpoint))) {
      if (!empty) for (Object[] row : VERSIONS) {
        descriptions.add(description(row));
        if ((Boolean) row[3]) PluginObjectSnapshotQualification.put(store, (String) row[0], (PluginKind) row[1]);
      }
    }
    Path seed = Path.of("/control/objects.json"); Files.createFile(seed, PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rw-------")));
    Files.write(seed, PluginObjectSnapshotApplication.encoded(Collections.singletonMap("objects", descriptions)));
    VersityStorageApplication.result("GENERATED_RECOVERY_SOURCE_PREPARED", Collections.singletonMap("objectCount", empty ? 0 : 6));
  }
  static void verify(boolean empty) throws Exception {
    VersityStorageApplication.Settings settings = new VersityStorageApplication.Settings(false);
    URI endpoint = URI.create(System.getenv("PLUGIN_STORAGE_S3_ENDPOINT"));
    Map<String, Long> expected = new TreeMap<>(); int registryCount = 0;
    try (MongoClient mongo = new MongoClient(new MongoClientURI("mongodb://recovered-mongo:27017/" + DATABASE
             + "?serverSelectionTimeoutMS=3000&connectTimeoutMS=3000&socketTimeoutMS=5000"));
         S3ArtifactObjectStore store = S3ArtifactObjectStore.connect(PluginObjectSnapshotApplication.properties(settings, endpoint));
         var s3 = VersityStorageApplication.client(settings, endpoint, false)) {
      var db = mongo.getDatabase(DATABASE);
      require(db.getCollection("users").countDocuments() == 1);
      if (!empty) {
        for (Object[] row : VERSIONS) {
          PluginArtifact artifact = artifact(row);
          if (!row[2].equals("ORPHAN")) {
            registryCount++; Document actual = db.getCollection("plugin-artifact").find(eq("_id", artifact.getId())).first();
            require(actual != null && actual.getString("state").equals(row[2]) && actual.getString("kind").equals(row[1].toString())
                && actual.getString("sha256").equals(artifact.getSha256()) && ((Number) actual.get("sizeBytes")).longValue() == artifact.getSizeBytes()
                && actual.getString("objectKey").equals(artifact.getObjectKey()));
          }
          if ((Boolean) row[3]) {
            expected.put(artifact.getObjectKey(), artifact.getSizeBytes());
            try (InputStream stream = store.open(artifact)) { ArtifactIntegrity.copyVerified(stream, java.io.OutputStream.nullOutputStream(), artifact); }
            var metadata = s3.headObject(b -> b.bucket(settings.bucket).key(artifact.getObjectKey()));
            require(metadata.contentLength() == artifact.getSizeBytes() && PluginObjectSnapshotApplication.CONTENT_TYPE.equals(metadata.contentType())
                && metadata.metadata().equals(Collections.singletonMap("sha256", artifact.getSha256())));
          }
        }
        Document current = db.getCollection("analytics-technique").find(eq("_id", "current-method")).first();
        Document older = db.getCollection("analytics-technique").find(eq("_id", "older-method")).first();
        require(current != null && current.getString("artifactId").equals(artifact(VERSIONS[0]).getId()));
        require(older != null && !older.getBoolean("enabled") && older.getString("artifactId").equals(artifact(VERSIONS[1]).getId())
            && older.getString("previousId").equals("current-method") && older.getString("pluginFamilyId").equals(artifact(VERSIONS[0]).getId()));
        Document indicator = db.getCollection("analytics-indicator").find().first();
        DBRef selected = (DBRef) indicator.get("analyticsTechniqueReference", Document.class).get("analyticsTechnique");
        require(selected.getCollectionName().equals("analytics-technique") && selected.getId().equals(current.get("_id")));
        require(VersityStorageApplication.JSON.readTree(db.getCollection("analytics-indicator-drafts").find().first().getString("session")).path("method").asText().equals(older.get("_id")));
        Document removed = db.getCollection("visualization-library").find(eq("_id", "removed-library")).first();
        require(removed != null && removed.getString("removalState").equals("REMOVED") && removed.getString("artifactId").equals(artifact(VERSIONS[2]).getId()));
        require(db.getCollection("plugin-installation").find(eq("_id", "discarded-installation")).first().getString("state").equals("DISCARDED"));
        require(db.getCollection("plugin-removal").countDocuments() == 2 && db.getCollection("plugin-version-family").countDocuments() == 1);
      }
      require(db.getCollection("plugin-artifact").countDocuments() == registryCount);
      require(expected.equals(PluginObjectSnapshotApplication.inventory(s3, settings.bucket)));
    }
    Map<String, Object> result = new LinkedHashMap<>(); result.put("objectCount", expected.size()); result.put("registryCount", registryCount);
    result.put("coldDatabaseAssociationsVerified", true); result.put("coldObjectBytesAndMetadataVerified", true); result.put("pluginExecuted", false);
    VersityStorageApplication.result("GENERATED_COMBINED_COLD_CLIENT_VERIFIED", result);
  }
  public static void main(String[] args) {
    try {
      require(args.length == 2 && (args[1].equals("empty") || args[1].equals("versions"))); boolean empty = args[1].equals("empty");
      if (args[0].equals("--prepare-source")) prepare(empty);
      else if (args[0].equals("--verify-cold")) verify(empty);
      else require(false);
    } catch (Throwable failure) { System.err.println("Generated combined recovery client failed."); System.exit(1); }
  }
}
